'use client';

import * as React from 'react';
import {createComponent} from '@lit/react';
import '@material/web/labs/gb/components/appbar/md-gb-app-bar.js';
import {AppBarElement} from '@material/web/labs/gb/components/appbar/app-bar-element.js';

/**
 * A Material Design app bar component. Wraps <md-gb-app-bar>.
 * Docs: https://material-web.dev/3.0/components/app-bar/
 */
export const MdAppBar = createComponent({
  react: React,
  tagName: 'md-gb-app-bar',
  elementClass: AppBarElement,
});

export type MdAppBarProps = React.ComponentProps<typeof MdAppBar>;
